def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        total = 0
        for i, char in enumerate(isbn[:-1]):
            if char.isdigit():
                total += (i + 1) * int(char)
            else:
                total += (i + 1) * 10
        return str((11 - (total % 11)) % 11)

    isbn_parts = isbn.split('-')
    if len(isbn_parts) != 4:
        raise ValueError("Invalid ISBN format")

    calculated_checksum = calculate_checksum(isbn[:-1])
    if isbn[-1].isdigit() and isbn[-1] == calculated_checksum:
        return "Right"
    elif isbn[-1].upper() == 'X' and calculated_checksum == '1':
        return isbn[:-1] + calculated_checksum
    else:
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if not (1 <= M <= 100 and 1 <= N <= 100 and 0 <= K <= M and 0 <= L <= N and 0 <= D <= M * N):
        raise ValueError("Invalid input for M, N, K, L, or D")

    if not all(1 <= xi, yi, pi, qi <= N for xi, yi, pi, qi in chatting_pairs):
        raise ValueError("Invalid student positions in chatting_pairs")

    row_separations = [0] * (M + 1)
    col_separations = [0] * (N + 1)

    for xi, yi, pi, qi in chatting_pairs:
        if yi == qi:
            if xi < pi:
                row_separations[xi] += 1
            else:
                row_separations[pi] += 1
        elif xi == pi:
            if yi < qi:
                col_separations[yi] += 1
            else:
                col_separations[qi] += 1

    best_rows = sorted(range(1, M + 1), key=lambda r: -row_separations[r])[:K]
    best_cols = sorted(range(1, N + 1), key=lambda c: -col_separations[c])[:L]

    return ' '.join(map(str, best_rows)), ' '.join(map(str, best_cols))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input values")
    if n == 1 and m == 0:
        return 1
    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for passes in range(1, m + 1):
        dp[0][passes] = dp[n-1][passes-1]
        dp[n-1][passes] = dp[0][passes-1]
        for i in range(1, n-1):
            dp[i][passes] = dp[i-1][passes-1] + dp[i+1][passes-1]
    return dp[0][m]

