def max_energy(beads):
    n = len(beads)
    if n == 0:
        return 0

    # Create a 3D DP array dp[i][j][k] where i <= j <= k
    dp = [[[0 for _ in range(n)] for _ in range(n)] for _ in range(n)]

    # Base case: single bead
    for i in range(n):
        dp[i][i][(i + 1) % n] = 0

    # Fill the DP array
    for length in range(2, n + 1):
        for i in range(n):
            j = (i + length - 1) % n
            k = (j + 1) % n
            for m in range(i + 1, j):
                dp[i][j][k] = max(dp[i][j][k], beads[i] * beads[m] * beads[k] + dp[i][m][k] + dp[m][j][k])

    return dp[0][n - 1][0]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if coeff == 1 and i > 1:
            term = f'x^{i}'
        elif coeff == -1 and i > 1:
            term = f'-x^{i}'
        elif coeff == 1 and i == 1:
            term = 'x'
        elif coeff == -1 and i == 1:
            term = '-x'
        elif coeff == 1 and i == 0:
            term = '1'
        elif coeff == -1 and i == 0:
            term = '-1'
        elif i > 1:
            term = f'{abs(coeff)}x^{i}'
        elif i == 1:
            term = f'{abs(coeff)}x'
        else:
            term = str(abs(coeff))
        if i > 0:
            if coeffs[i-1] >= 0:
                term = '+' + term
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    cipher_map = {}
    for e, o in zip(encoded, original):
        if e in cipher_map:
            if cipher_map[e] != o:
                return "Failed"
        else:
            cipher_map[e] = o

    if len(cipher_map) != len(set(cipher_map.values())):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in cipher_map:
            decoded_message.append(cipher_map[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    if n <= 1 or not isinstance(n, int):
        raise ValueError("Input must be a positive integer greater than 1")

    # Start checking for factors from the smallest prime number
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            return n // factor
        factor += 1

    # If no factors found, then n itself is a prime number
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    if n == k * x:
        return 1
    return count_partitions(n - x, k - 1, x) + count_partitions(n, k, x + 1)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0 or last <= 0:
        return 0
    if n > last:
        return 0
    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n + 1, i, memo)

    memo[last] = count
    return count

