def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    if not isinstance(n, int) or not isinstance(rules, list):
        raise ValueError("Invalid input types")

    visited = set()
    queue = deque([n])

    while queue:
        current = queue.popleft()
        if current not in visited:
            visited.add(current)
            digits = list(str(current))
            for i, digit in enumerate(digits):
                for x, y in rules:
                    if int(digit) == x:
                        new_digits = digits[:]
                        new_digits[i] = str(y)
                        new_number = int(''.join(new_digits))
                        queue.append(new_number)

    return len(visited)

