def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("Invalid system. Must be either 11 or 21 points.")

    games = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Invalid point. Must be either 'W' or 'L'.")

        if (player_score >= system and player_score - opponent_score >= 2) or \
           (opponent_score >= system and opponent_score - player_score >= 2):
            games.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        games.append(f"{player_score}:{opponent_score}")

    return games

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Initialize an array to store the Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0] = 1

    # Compute the Catalan numbers using dynamic programming
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        raise ValueError("The length of the road must be a positive integer.")

    if any(start < 0 or end >= l or start > end for start, end in areas):
        raise ValueError("Clearing areas must be within the bounds of the road and start before end.")

    cleared_positions = set()
    for start, end in areas:
        cleared_positions.update(range(start, end + 1))

    remaining_trees = l - len(cleared_positions)
    return remaining_trees

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum value at each time limit
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the DP table from the back to avoid overwriting values
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value at time T is the answer
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    max_occupied_volume = dp[-1]
    return V - max_occupied_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    if m == 0:
        return 1
    if n == 0:
        return 0

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c: str, k: str) -> str:
        if not c.isalpha() or not k.isalpha():
            raise ValueError("Input characters must be alphabetic.")
        base = ord('A') if c.isupper() else ord('a')
        return chr((ord(c) - ord(k) - base) % 26 + base)

    key_length = len(key)
    plaintext = ''.join(shift_char(ciphertext[i], key[i % key_length]) for i in range(len(ciphertext)))
    return plaintext

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0

    for day, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day

    return most_unhappy_day

def jinjin_savings_plan(budgets: List[int]) -> int:
    if len(budgets) != 12:
        raise ValueError("The budgets list must contain exactly 12 integers.")

    total_savings = 0
    pocket_money = 300

    for month in range(12):
        remaining_money = pocket_money - budgets[month]

        if remaining_money < 100:
            return -month

        savings = (remaining_money // 100) * 100
        total_savings += savings

    total_savings += int(total_savings * 0.20)
    return total_savings

def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    increase = [1] * n
    decrease = [1] * n

    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                increase[i] = max(increase[i], increase[j] + 1)

    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                decrease[i] = max(decrease[i], decrease[j] + 1)

    max_choir_length = 1
    for i in range(n):
        max_choir_length = max(max_choir_length, increase[i] + decrease[i] - 1)

    return n - max_choir_length

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("n must be a positive integer")
    return 2 ** (2 * n) - 2
